export const kwpText = (v) => {
  const n = Number(v);
  if (!Number.isFinite(n) || n <= 0) return "–";
  return n >= 1000 ? `${(n / 1000).toLocaleString("de-DE", { maximumFractionDigits: 2 })} MWp` : `${n.toLocaleString("de-DE", { maximumFractionDigits: 1 })} kWp`;
};

