          platz(14);
          s.text(RAND + 2, y, "•", { groesse: 10, farbe: F.ov600 });
          absatz(p, { einzug: 14 });
        }
        y += 6;
      }
      if (a.tabelle) tabelle(a.tabelle);
    }
  }
  if (s) fuss();
  return doc.alsBuffer();
}
