}

for rel, inhalt in DATEIEN.items():
    p = os.path.join(W, rel)
    if os.path.exists(p):
        raise SystemExit(f"existiert bereits: {p}")
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "w", encoding="utf-8", newline="\n") as f:
        f.write(inhalt)
    print("geschrieben", rel)

