    akten = (await closingBackend().gbZuBezug(nutzer, { bezugArt, bezugId })).akten || [];
  } catch {
    return null;
  }
  if (!akten.length) return null;
  return <GrundbuchKurz akten={akten} admin={akten[0]?.meineRolle === "backoffice"} />;
}

