def gnotkg_tabelle_b(wert):
	w = max(0.0, float(wert or 0))
	geb = _STUFEN_B[0][2]
	bis = _STUFEN_B[0][0]
	for grenze, schritt, plus in _STUFEN_B[1:]:
		if w <= bis:
			break
		teil = min(w, grenze) - bis
		geb += math.ceil(teil / schritt) * plus
		bis = grenze
	return geb


