		"schluessel": c["schluessel"], "reihenfolge": i + 1, "label": c["label"], "text": c["text"], "verantwortlich": c["verantwortlich"],
		"frist": _plus_tage(heute, c["fristTage"]), "status": "offen", "nachweis": "", "erfuelltAm": "",
	} for i, c in enumerate(liste)]


def signing_anlegen():
