def meilensteine_bereinigen(liste, kaufpreis):
	out = []
	for m in (liste or [])[:8]:
		m = m or {}
		x = {
			"label": str(m.get("label") or "").strip()[:120], "betrag": max(0, _r(float(m.get("betrag") or 0))), "bedingung": str(m.get("bedingung") or "").strip()[:200],
