// Grundbuch & Closing – wenige gebündelte Aufnahmen, EIN Browser, danach geschlossen.
// Aufruf: node cl_shot.mjs
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const B = "http://localhost:3100";
const b = await chromium.launch();
try {
  const kontext = async (email, breite) => {
    const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 }, deviceScaleFactor: 1 });
    const r0 = await ctx.request.post(B + "/api/auth/login", { headers: { Origin: B }, data: { email, passwort: "Demo-2026!" }, timeout: 180000 });
    if (r0.status() !== 200) throw new Error("Login " + email + " " + r0.status());
    return ctx;
  };
  const admin = await kontext("admin@example.com", 1440);
  const akten = (await (await admin.request.get(B + "/api/admin/grundbuch?status=", { timeout: 180000 })).json()).akten;
  const muehl = akten.find((a) => /Mühlweg/.test(a.titel));
  const cls = (await (await admin.request.get(B + "/api/admin/closing?status=", { timeout: 180000 })).json()).closings;
  const inn = cls.find((c) => /Innviertel/.test(c.projekt?.titel || "")) || cls[0];
  const auf = async (ctx, pfad, name, voll = false) => {
    const p = await ctx.newPage();
    const fehler = [];
    p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
    p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
    const r = await p.goto(B + pfad, { waitUntil: "load", timeout: 180000 });
    await p.waitForTimeout(2500);
    const ueber = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    const breite = p.viewportSize().width;
    await p.screenshot({ path: fileURLToPath(new URL(`./shots/${name}_${breite}.png`, import.meta.url)), fullPage: voll });
    console.log(r.status(), `${name}_${breite}.png`, "Überlauf", ueber, fehler.length ? "\n" + fehler.join("\n") : "");
    await p.close();
  };
  await auf(admin, "/portal/admin/grundbuch", "cl_gb_liste");
  if (muehl) await auf(admin, `/portal/admin/grundbuch/${muehl.id}`, "cl_gb_akte", true);
  if (inn) await auf(admin, `/portal/admin/closing/${inn.id}`, "cl_closing_admin", true);
  await admin.close();
  const fl = await kontext("flaeche@example.com", 390);
  if (muehl) await auf(fl, `/portal/grundbuch/${muehl.id}`, "cl_gb_eigentuemer", true);
  await fl.close();
  const inv = await kontext("investor@example.com", 390);
  if (inn) await auf(inv, `/portal/closing/${inn.id}`, "cl_closing_investor", true);
  await inv.close();
} finally {
  await b.close();
}
